import { Channel, invoke, type InvokeOptions } from '@tauri-apps/api/core'
import { listen, type UnlistenFn } from '@tauri-apps/api/event'

export { Channel }

/** Runs the command `command` by calling `invoke` with the options it sends, such as
 * headers. */
export type Runner = <T>(
  command: string,
  invoke: (options?: InvokeOptions) => Promise<T>,
) => Promise<T>

let runner: Runner = (_, invoke) => invoke()

/** Sets how every command runs, such as in a span whose trace it sends as headers. */
export function setRunner(next: Runner): void {
  runner = next
}

/**
 *  `[agent]`: the agent's model, how much it reasons, and how long a run
 *  goes.
 */
export type AgentConfig = {
  /**  A `vendor/model` reference, as koharu-llm connects one. */
  model?: string | null
  /**
   *  How much the model reasons before it answers: off, or one of rig's
   *  portable levels after OpenAI's `reasoning_effort`, written as one word;
   *  the model's own default when unset. rig refuses off for a model that
   *  can't stop reasoning.
   */
  reasoning?: string | null
  /**  How many model calls a run makes at most. */
  max_turns?: number
  /**  How many times a run lets the model correct a call it wrote wrong. */
  corrections?: number
}

/**
 *  What an agent run tells the panel: the agent's events as they come, then
 *  how it ended. A cancelled run tells nothing more.
 */
export type AgentEvent =
  | { type: 'event'; event: Event }
  | { type: 'completed'; answer: string }
  | { type: 'failed'; error: string }

export type Align = 'start' | 'center' | 'end' | 'justify'

/**
 *  Where the lines sit along a frame's block axis, which follows the writing
 *  direction.
 */
export type Anchor = 'start' | 'center' | 'end'

export type Answer = ProjectAnswer | Page | Layer | LayerId[] | History

/**
 *  A painted area of a page: a byte a pixel over `rect`, in page pixels,
 *  painted where it isn't 0.
 */
export type Area = {
  rect: Rect
  pixels: number[]
}

/**
 *  The imported file a page was made from, drawn under every layer, as
 *  Photoshop's one Background is.
 */
export type Background = {
  file: Hash
  visible: boolean
}

/**
 *  A balloon of the page, holding its texts. Its outline is never drawn or
 *  filled, because the page's background already shows it.
 */
export type Balloon = {
  /**  A closed path in page coordinates. */
  outline: Path
}

export type Blend =
  | 'normal'
  | 'multiply'
  | 'screen'
  | 'overlay'
  | 'darken'
  | 'lighten'
  | 'color_dodge'
  | 'color_burn'
  | 'hard_light'
  | 'soft_light'
  | 'difference'
  | 'exclusion'
  | 'hue'
  | 'saturation'
  | 'color'
  | 'luminosity'
  /**  Containers only: children blend with what is below the container. */
  | 'pass_through'

/**
 *  One text of the page, in a fixed shape: its source and its translation,
 *  both text values, as an XLIFF segment's source and target share one
 *  content model, and two layers of its own, its `mask` and its `cleanup`, as
 *  Photoshop's Generative Fill puts its result on a layer with a layer mask.
 *  A patch on the block reaches its parts; painting them takes their own ids.
 */
export type Block = {
  role?: Role
  /**
   *  The original text, never drawn, in a box or a closed path, as a
   *  PAGE-XML text region records it.
   */
  source: Text
  /**  As an XLIFF segment holds zero or one target. */
  translation?: Text | null
  /**
   *  Where the source's glyphs are: the clean-up shows only inside it while
   *  it's visible.
   */
  mask?: Layer<Mask>
  /**  The scan redrawn without the source's glyphs, under the translation. */
  cleanup?: Layer<Raster>
}

/**  A rectangle in page pixels, for text frames. */
export type Bounds = {
  x: number
  y: number
  width: number
  height: number
}

/**  The brush the draw, eraser, and remove tools stroke with. */
